-- Generated by `make contracts` from contracts/cdc_nndss_weekly.odcs.yaml. Do not edit: change the contract and regenerate.
-- Types the latest raw load only; every business rule lives in intermediate models.
with raw as (
    select * from {{ source('raw', 'cdc_nndss_weekly') }}
),

latest as (
    select * from raw where filename = (select max(filename) from raw)
)

select
  "states" AS "states",
  CASE WHEN CAST(NULLIF(trim("year"), '') AS DECIMAL(38, 6)) IS NULL THEN NULL WHEN CAST(NULLIF(trim("year"), '') AS DECIMAL(38, 6)) = trunc(CAST(NULLIF(trim("year"), '') AS DECIMAL(38, 6))) THEN CAST(CAST(NULLIF(trim("year"), '') AS DECIMAL(38, 6)) AS BIGINT) ELSE error('year: a value has a fraction, so it isn''t a whole count; check the contract') END AS "year",
  CASE WHEN CAST(NULLIF(trim("week"), '') AS DECIMAL(38, 6)) IS NULL THEN NULL WHEN CAST(NULLIF(trim("week"), '') AS DECIMAL(38, 6)) = trunc(CAST(NULLIF(trim("week"), '') AS DECIMAL(38, 6))) THEN CAST(CAST(NULLIF(trim("week"), '') AS DECIMAL(38, 6)) AS BIGINT) ELSE error('week: a value has a fraction, so it isn''t a whole count; check the contract') END AS "week",
  "label" AS "label",
  CASE WHEN CAST(NULLIF(trim("m1"), '') AS DECIMAL(38, 6)) IS NULL THEN NULL WHEN CAST(NULLIF(trim("m1"), '') AS DECIMAL(38, 6)) = trunc(CAST(NULLIF(trim("m1"), '') AS DECIMAL(38, 6))) THEN CAST(CAST(NULLIF(trim("m1"), '') AS DECIMAL(38, 6)) AS BIGINT) ELSE error('m1: a value has a fraction, so it isn''t a whole count; check the contract') END AS "m1",
  "m1_flag" AS "m1_flag",
  CASE WHEN CAST(NULLIF(trim("m2"), '') AS DECIMAL(38, 6)) IS NULL THEN NULL WHEN CAST(NULLIF(trim("m2"), '') AS DECIMAL(38, 6)) = trunc(CAST(NULLIF(trim("m2"), '') AS DECIMAL(38, 6))) THEN CAST(CAST(NULLIF(trim("m2"), '') AS DECIMAL(38, 6)) AS BIGINT) ELSE error('m2: a value has a fraction, so it isn''t a whole count; check the contract') END AS "m2",
  "m2_flag" AS "m2_flag",
  CASE WHEN CAST(NULLIF(trim("m3"), '') AS DECIMAL(38, 6)) IS NULL THEN NULL WHEN CAST(NULLIF(trim("m3"), '') AS DECIMAL(38, 6)) = trunc(CAST(NULLIF(trim("m3"), '') AS DECIMAL(38, 6))) THEN CAST(CAST(NULLIF(trim("m3"), '') AS DECIMAL(38, 6)) AS BIGINT) ELSE error('m3: a value has a fraction, so it isn''t a whole count; check the contract') END AS "m3",
  "m3_flag" AS "m3_flag",
  CASE WHEN CAST(NULLIF(trim("m4"), '') AS DECIMAL(38, 6)) IS NULL THEN NULL WHEN CAST(NULLIF(trim("m4"), '') AS DECIMAL(38, 6)) = trunc(CAST(NULLIF(trim("m4"), '') AS DECIMAL(38, 6))) THEN CAST(CAST(NULLIF(trim("m4"), '') AS DECIMAL(38, 6)) AS BIGINT) ELSE error('m4: a value has a fraction, so it isn''t a whole count; check the contract') END AS "m4",
  "m4_flag" AS "m4_flag",
  "location1" AS "location1",
  "location2" AS "location2",
  "sort_order" AS "sort_order"
from latest
